ALLOWED_SORT_COLUMNS = {"created_at", "total", "status", "id"}

@orders_bp.route("/sorted", methods=["GET"])
@require_role("manager")
def sorted_orders():
    sort_by = request.args.get("sort_by", "created_at")
    if sort_by not in ALLOWED_SORT_COLUMNS:
        return jsonify({"error": "invalid sort column"}), 400
    session = get_session()
    rows = session.execute(
        text(f"SELECT id, user_id, status, total FROM orders ORDER BY {sort_by}")
    )

@orders_bp.route("/all", methods=["GET"])
@require_role("manager")
def all_orders():
    """List every order. Managers and admins only."""
    session = get_session()
    orders = session.query(Order).order_by(Order.created_at.desc()).all()
    return jsonify([o.to_dict() for o in orders])

def require_role(minimum_role: str):
    """Require at least the given role (user < manager < admin)."""
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            user = get_current_user()
            if user is None:
                return jsonify({"error": "authentication required"}), 401
            if ROLE_RANK.get(user.role, 0) < ROLE_RANK.get(minimum_role, 99):
                return jsonify({"error": "insufficient role"}), 403
            g.current_user = user
            return fn(*args, **kwargs)
        return wrapper
    return decorator
